/// <summary>
/// PaffH 02.11.22
/// build tree structure and save to NDXPAInfo table
/// </summary>
/// <param name="_sender">FormControl</param>
/// <param name="_e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXPAInfo, FormButtongetPAInfo), FormControlEventType::Clicked),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void FormButtongetPAInfo_OnClicked(FormControl _sender, FormControlEventArgs _e)
{
    FormRun formRunCaller = _sender.formRun();
    FormDataSource ProdTable_2_DS = formRunCaller.dataHelper().FindDataSource(formDataSourceStr(NDXPAInfo,ProdTable_2));
    NDXPAInfoClass::buildPATreeStructureFromProdTable(ProdTable_2_DS.cursor());
    ProdTable_2_DS.reread();
}

/// <summary>
/// PaffH 28.12.22
/// </summary>
/// <param name="_sender">FormControl</param>
/// <param name="_e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXPAInfo, FormButtongetPAInfoAll), FormControlEventType::Clicked),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void FormButtongetPAInfoAll_OnClicked(FormControl _sender, FormControlEventArgs _e)
{
    FormRun formRunCaller = _sender.formRun();
    FormDataSource ProdTable_2_DS = formRunCaller.dataHelper().FindDataSource(formDataSourceStr(NDXPAInfo,ProdTable_2));
    NDXPAInfoClass::getAllPAInfo(ProdTable_2_DS);
    ProdTable_2_DS.reread();
}

/// <summary>
/// PaffH 03.11.22
/// build tree structure
/// </summary>
/// <param name="_sender">FormDataSource</param>
/// <param name="_e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(NDXPAInfo, ProdTable_2), FormDataSourceEventType::Activated),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter required by the event interface.')]
public static void ProdTable_2_OnActivated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    FormRun formRun = _sender.formRun();
    if (formRun is NDXPAInfoI)
    {
        NDXPAInfoI nDXPAInfo = formRun as NDXPAInfoI;
        nDXPAInfo.setInfoText(nDXPAInfo.buildTreeStructure());
    }
}
